export function Template(e){const t=new String(e);return new Proxy(t,{get:(e,t)=>"interpolate"===t?function(t,r,n=[]){try{let r=(new DOMParser).parseFromString(e,"text/html");r.querySelectorAll("[data-access]").forEach((e=>{let t=e.getAttribute("data-access");n.includes(t)||e.parentNode.removeChild(e)}));let o=(new XMLSerializer).serializeToString(r);o=o.replace(/<!DOCTYPE html>.*<body>/,""),o=o.replace(/<\/body>.*<\/html>/,"");const c=Object.keys(t),l=Object.values(t);return new Function(...c,`return \`${o}\`;`)(...l)}catch(e){window.console.log("INTERPOLATION ERROR",e)}}:"function"==typeof e[t]?e[t].bind(e):e[t]})}